/**
 * App strings in every App Store language.
 *
 *   t('profile.title')                       → "Profile"
 *   t('effect.pickShorterVideo', { max: 10 }) → "Pick a video of 10 seconds or less…"
 *   tp('common.credits', 5)                  → "5 credits" (plural form per language)
 *
 * en.json is the source. The other files are generated by scripts/translate.mjs;
 * a key missing there falls back to English. The language follows the device (and
 * iOS Settings → Boson AI → Language); iOS restarts the app when it changes.
 */
import { getLocales } from 'expo-localization';
import en from './locales/en.json';

type Dict = Record<string, string>;
export type Params = Record<string, string | number>;

/** iOS localization ids (CFBundleLocalizations), same as the files in ./locales. */
export const SUPPORTED_LOCALES = [
  'en', 'ar', 'bn', 'ca', 'cs', 'da', 'de', 'el', 'es', 'es-MX', 'fi', 'fr', 'fr-CA', 'gu', 'he', 'hi', 'hr',
  'hu', 'id', 'it', 'ja', 'kn', 'ko', 'ml', 'mr', 'ms', 'nb', 'nl', 'or', 'pa', 'pl', 'pt-BR', 'pt-PT', 'ro',
  'ru', 'sk', 'sl', 'sv', 'ta', 'te', 'th', 'tr', 'uk', 'ur', 'vi', 'zh-Hans', 'zh-Hant',
] as const;
export type AppLocale = (typeof SUPPORTED_LOCALES)[number];

// Static requires so Metro bundles every file; each is parsed only when used.
const LOADERS: Record<Exclude<AppLocale, 'en'>, () => Dict> = {
  ar: () => require('./locales/ar.json'),
  bn: () => require('./locales/bn.json'),
  ca: () => require('./locales/ca.json'),
  cs: () => require('./locales/cs.json'),
  da: () => require('./locales/da.json'),
  de: () => require('./locales/de.json'),
  el: () => require('./locales/el.json'),
  es: () => require('./locales/es.json'),
  'es-MX': () => require('./locales/es-MX.json'),
  fi: () => require('./locales/fi.json'),
  fr: () => require('./locales/fr.json'),
  'fr-CA': () => require('./locales/fr-CA.json'),
  gu: () => require('./locales/gu.json'),
  he: () => require('./locales/he.json'),
  hi: () => require('./locales/hi.json'),
  hr: () => require('./locales/hr.json'),
  hu: () => require('./locales/hu.json'),
  id: () => require('./locales/id.json'),
  it: () => require('./locales/it.json'),
  ja: () => require('./locales/ja.json'),
  kn: () => require('./locales/kn.json'),
  ko: () => require('./locales/ko.json'),
  ml: () => require('./locales/ml.json'),
  mr: () => require('./locales/mr.json'),
  ms: () => require('./locales/ms.json'),
  nb: () => require('./locales/nb.json'),
  nl: () => require('./locales/nl.json'),
  or: () => require('./locales/or.json'),
  pa: () => require('./locales/pa.json'),
  pl: () => require('./locales/pl.json'),
  'pt-BR': () => require('./locales/pt-BR.json'),
  'pt-PT': () => require('./locales/pt-PT.json'),
  ro: () => require('./locales/ro.json'),
  ru: () => require('./locales/ru.json'),
  sk: () => require('./locales/sk.json'),
  sl: () => require('./locales/sl.json'),
  sv: () => require('./locales/sv.json'),
  ta: () => require('./locales/ta.json'),
  te: () => require('./locales/te.json'),
  th: () => require('./locales/th.json'),
  tr: () => require('./locales/tr.json'),
  uk: () => require('./locales/uk.json'),
  ur: () => require('./locales/ur.json'),
  vi: () => require('./locales/vi.json'),
  'zh-Hans': () => require('./locales/zh-Hans.json'),
  'zh-Hant': () => require('./locales/zh-Hant.json'),
};

/** Maps a device language tag (e.g. "pt-BR", "zh-Hant-TW", "es-AR", "no") to one of ours. */
export function matchLocale(tag: string): AppLocale | null {
  const parts = tag.replace('_', '-').split('-');
  const lang = parts[0].toLowerCase();
  const rest = parts.slice(1).map((p) => p.toUpperCase());
  const has = (x: string) => rest.includes(x.toUpperCase());
  if (lang === 'zh') return has('Hant') || has('TW') || has('HK') || has('MO') ? 'zh-Hant' : 'zh-Hans';
  if (lang === 'pt') return has('BR') ? 'pt-BR' : 'pt-PT';
  if (lang === 'es') return has('ES') || rest.length === 0 ? 'es' : 'es-MX'; // Latin American Spanish
  if (lang === 'fr') return has('CA') ? 'fr-CA' : 'fr';
  if (lang === 'no' || lang === 'nn' || lang === 'nb') return 'nb';
  if (lang === 'iw') return 'he';
  if (lang === 'in') return 'id';
  return (SUPPORTED_LOCALES as readonly string[]).includes(lang) ? (lang as AppLocale) : null;
}

function deviceLocale(): AppLocale {
  try {
    for (const l of getLocales()) {
      const match = matchLocale(l.languageTag);
      if (match) return match;
    }
  } catch {
    // web / tests
  }
  return 'en';
}

export const locale: AppLocale = deviceLocale();
/** BCP 47 tag for Intl / toLocaleString. */
export const intlLocale = locale;
export const isRTL = locale === 'ar' || locale === 'he' || locale === 'ur';

const base: Dict = en as Dict;
const dict: Dict = locale === 'en' ? base : { ...base, ...safeLoad(locale) };

function safeLoad(l: Exclude<AppLocale, 'en'>): Dict {
  try {
    return LOADERS[l]();
  } catch {
    return {};
  }
}

function fill(text: string, params?: Params): string {
  if (!params) return text;
  return text.replace(/\{(\w+)\}/g, (m, k: string) => (k in params ? String(params[k]) : m));
}

/** Translated string for `key`; falls back to English, then to `fallback`, then to the key. */
export function t(key: string, params?: Params, fallback?: string): string {
  const text = dict[key] ?? fallback ?? key;
  return fill(text, params);
}

/** Like t() but only if the key exists (for content that may not be translated). */
export function tMaybe(key: string, fallback: string, params?: Params): string {
  const text = dict[key];
  return text === undefined ? fill(fallback, params) : fill(text, params);
}

let plurals: Intl.PluralRules | null = null;
function pluralCategory(n: number): string {
  try {
    plurals ??= new Intl.PluralRules(intlLocale);
    return plurals.select(n);
  } catch {
    return n === 1 ? 'one' : 'other';
  }
}

/**
 * Plural-aware string. Looks up `${key}_${category}` (zero/one/two/few/many/other,
 * per Intl.PluralRules for the current language), then `${key}_other`. `{count}` is filled in.
 */
export function tp(key: string, count: number, params?: Params): string {
  const all = { count: formatNumber(count), ...params };
  const text = dict[`${key}_${pluralCategory(count)}`] ?? dict[`${key}_other`] ?? base[`${key}_other`] ?? key;
  return fill(text, all);
}

export function formatNumber(n: number): string {
  try {
    return n.toLocaleString(intlLocale);
  } catch {
    return String(n);
  }
}

export function formatDate(iso: string | Date): string {
  const d = typeof iso === 'string' ? new Date(iso) : iso;
  try {
    return d.toLocaleDateString(intlLocale);
  } catch {
    return d.toDateString();
  }
}
